draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 20);
  ctx.lineTo(W/2 - 30, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 20);
  ctx.lineTo(W/2 + 30, H/2 + 10);
  ctx.stroke();

  // wing movement
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 10);
  ctx.lineTo(W/2 - 40, H/2 - 10 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 10);
  ctx.lineTo(W/2 + 40, H/2 - 10 + 20 * Math.sin(t + Math.PI));
  ctx.stroke();

  ctx.restore();
}
